WITH p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),e AS (SELECT id_empreendimento,produto,finalidade FROM `basedosdados.br_bcb_sicor.empreendimento`),op AS (SELECT op.* FROM p JOIN car USING(id_car_norm) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) WHERE op.ano_emissao BETWEEN 2013 AND 2026) SELECT op.ano_emissao,COUNT(DISTINCT op.id_referencia_bacen) operacoes,COUNT(*) linhas,SUM(op.valor_parcela_credito) credito,SUM(op.area_financiada) area_financiada,STRING_AGG(DISTINCT e.produto,', ' ORDER BY e.produto) produtos,STRING_AGG(DISTINCT e.finalidade,', ') finalidades FROM op LEFT JOIN e USING(id_empreendimento) GROUP BY 1 ORDER BY 1